135	interface HeaderNavProps {
136	  tabs: HeaderNavTabItem[];
137	  activeTabId?: string | null;
138	}
139	
140	function useAutoActiveTabId(tabs: HeaderNavTabItem[]): string | undefined {
141	  const basePath = useResolvedPath('.').pathname;
142	  const { pathname } = useLocation();
143	
144	  return useMemo(() => {
145	    const allTabs = tabs.flatMap(tab => (isTabGroup(tab) ? tab.items : [tab]));
146	    const routeObjects = allTabs.map(tab => ({
147	      path: `${resolvePath(tab.href, basePath).pathname}/*`,
148	      id: tab.id,
149	    }));
150	    const matches = matchRoutes(routeObjects, pathname);
151	    return matches?.[0]?.route.id;
152	  }, [tabs, basePath, pathname]);
153	}
154	
155	function HeaderNavAutoDetect(props: { tabs: HeaderNavTabItem[] }) {
156	  const activeTabId = useAutoActiveTabId(props.tabs);
157	  return <HeaderNavInner tabs={props.tabs} activeTabId={activeTabId} />;
158	}
