160	function HeaderNavInner(props: HeaderNavProps) {
161	  const { tabs, activeTabId } = props;
162	  const { ownProps } = useDefinition(HeaderNavDefinition, {
163	    tabs,
164	    activeTabId,
165	  });
166	  const { classes } = ownProps;
167	
168	  const { isFocusVisible } = useFocusVisible();
169	  const navRef = useRef<HTMLElement>(null);
170	  const itemRefs = useRef<Map<string, HTMLElement>>(new Map());
171	
172	  const [highlightedKey, setHighlightedKey] = useState<string | null>(null);
173	
174	  // Resolve activeTabId to a top-level key (groups own their children's active state)
175	  const { activeKey, activeChildId } = useMemo(() => {
176	    if (!activeTabId) return { activeKey: undefined, activeChildId: undefined };
177	    for (const item of tabs) {
178	      if (isTabGroup(item)) {
179	        const child = item.items.find(c => c.id === activeTabId);
180	        if (child) {
181	          return { activeKey: item.id, activeChildId: child.id };
182	        }
183	      } else if (item.id === activeTabId) {
184	        return { activeKey: item.id, activeChildId: undefined };
185	      }
186	    }
187	    return { activeKey: undefined, activeChildId: undefined };
188	  }, [activeTabId, tabs]);
189	
190	  const registerRef = useCallback((key: string, el: HTMLElement | null) => {
191	    if (el) {
192	      itemRefs.current.set(key, el);
193	    } else {
194	      itemRefs.current.delete(key);
195	    }
196	  }, []);
197	
198	  return (
199	    <nav
200	      ref={navRef}
201	      aria-label="Content navigation"
202	      className={classes.root}
203	      data-focus-visible={isFocusVisible || undefined}
204	    >
205	      <ul role="list" className={classes.list}>
206	        {tabs.map(item =>
207	          isTabGroup(item) ? (
208	            <HeaderNavGroupItem
