17	import { useMemo, type ReactNode } from 'react';
18	import { RouterProvider } from 'react-aria-components';
19	import { useInRouterContext, useNavigate } from 'react-router-dom';
20	import { createVersionedValueMap } from '@backstage/version-bridge';
21	import { BUIContext } from '../analytics/useAnalytics';
22	import { useResolvedHref } from '../hooks/useResolvedHref';
23	import type { UseAnalyticsFn } from '../analytics/types';
24	
25	/** @public */
26	export type BUIProviderProps = {
27	  useAnalytics?: UseAnalyticsFn;
28	  children: ReactNode;
29	};
30	
31	/**
32	 * Provides integration capabilities to all descendant BUI components.
33	 *
34	 * @example
35	 * ```tsx
36	 * import { BUIProvider } from '@backstage/ui';
37	 * import { useAnalytics as useBackstageAnalytics } from '@backstage/core-plugin-api';
38	 *
39	 * function App() {
40	 *   return (
41	 *     <BUIProvider useAnalytics={useBackstageAnalytics}>
42	 *       <AppContent />
43	 *     </BUIProvider>
44	 *   );
45	 * }
46	 * ```
47	 *
48	 * @public
49	 */
50	export function BUIProvider(props: BUIProviderProps) {
51	  const { useAnalytics, children } = props;
52	  const value = useMemo(
53	    () =>
54	      createVersionedValueMap({
55	        1: { useAnalytics },
56	      }),
57	    [useAnalytics],
58	  );
59	
60	  const content = (
61	    <BUIContext.Provider value={value}>{children}</BUIContext.Provider>
62	  );
63	
64	  if (useInRouterContext()) {
65	    return <RoutedContent>{content}</RoutedContent>;
66	  }
67	
68	  return content;
69	}
70	
71	function RoutedContent({ children }: { children: ReactNode }) {
72	  const navigate = useNavigate();
73	  return (
74	    <RouterProvider navigate={navigate} useHref={useResolvedHref}>
75	      {children}
76	    </RouterProvider>
77	  );
78	}
